const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-87.160422, 56.271030);
  // Create a buffer around the point to get a region of interest, e.g., 5 km radius
  const roi = point.buffer(5000); // 5 km radius
  const scale = 1000; // Resolution for reduction

  const date1_start = '2020-07-28';
  const date1_end = '2020-07-30'; // July 29, 2020
  const date2_start = '2020-07-12';
  const date2_end = '2020-07-14'; // July 13, 2020

  // Function to mask clouds in Sentinel-2 images using the QA60 band
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale reflectances to 0-1
  }

  // Function to calculate NDSI for Sentinel-2
  function calculateNDSI(image) {
    // NDSI = (Green - SWIR1) / (Green + SWIR1)
    // Sentinel-2 bands: B3 = Green, B11 = SWIR1
    return image.normalizedDifference(['B3', 'B11']).rename('NDSI');
  }

  // 2. Data Acquisition & Check
  let collection1 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter out highly cloudy scenes
    .map(maskS2clouds)
    .map(calculateNDSI);

  let collection2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(calculateNDSI);

  const size1 = await collection1.size().getInfo();
  const size2 = await collection2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2020-07-29 Images: ${size1}`);
    console.log(`2020-07-13 Images: ${size2}`);
    console.log("C1");
    return;
  }

  // Get the least cloudy image for each period
  const image1 = await collection1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const image2 = await collection2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Processing & Calculation
  // Calculate NDSI mean for each image
  const ndsi1_reduction = await image1.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['NDSI']),
    geometry: roi,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const ndsi2_reduction = await image2.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['NDSI']),
    geometry: roi,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const ndsi1_mean = ndsi1_reduction ? ndsi1_reduction.NDSI : null;
  const ndsi2_mean = ndsi2_reduction ? ndsi2_reduction.NDSI : null;

  // Check valid pixels after masking
  const count1_reduction = await image1.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const count2_reduction = await image2.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const count1 = count1_reduction ? count1_reduction.NDSI : 0;
  const count2 = count2_reduction ? count2_reduction.NDSI : 0;

  console.log(`2020-07-29 Images: ${size1} (Cloud %: ${await image1.get('CLOUDY_PIXEL_PERCENTAGE').getInfo()})`);
  console.log(`2020-07-13 Images: ${size2} (Cloud %: ${await image2.get('CLOUDY_PIXEL_PERCENTAGE').getInfo()})`);

  if (count1 === 0 || count2 === 0) {
    console.log(`2020-07-29 Valid Pixels: ${count1}`);
    console.log(`2020-07-13 Valid Pixels: ${count2}`);
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  if (ndsi1_mean === null || isNaN(ndsi1_mean) || ndsi2_mean === null || isNaN(ndsi2_mean)) {
    console.log(`2020-07-29 NDSI Mean: ${ndsi1_mean}`);
    console.log(`2020-07-13 NDSI Mean: ${ndsi2_mean}`);
    console.log("C3");
    return;
  }

  console.log(`2020-07-29 NDSI Mean: ${ndsi1_mean.toFixed(3)} (Pixels: ${count1})`);
  console.log(`2020-07-13 NDSI Mean: ${ndsi2_mean.toFixed(3)} (Pixels: ${count2})`);

  // Higher NDSI value indicates more snow/ice.
  if (ndsi1_mean > ndsi2_mean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
